"""A producer's autogenerated revision changes only the producer's own tables (#108)."""

from __future__ import annotations

from alembic.autogenerate import produce_migrations
from alembic.migration import MigrationContext
from alembic.operations import ops
from sqlalchemy import ForeignKey, MetaData, String, inspect
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

from metatables import PlatformManagedMetaTable, sqlalchemy_naming_convention
from metatables.migrations import (
    build_alembic_version_metatable,
    build_metatable_migration_provider,
)
from msm.models import AssetTable, CalendarTable, IndexTable, PortfolioTable
from msm.models.index_formulas import IndexFormulaDefinitionTable
from msm.storage_instances import configured_time_index_instance
from msm.time_index.indices import configured_index_values_storage
from msm_portfolios.time_index.contract_instances import (
    configured_portfolio_calendar_events_storage,
    configured_portfolio_event_ledger_storage,
    configured_portfolio_rebalance_state_storage,
)
from msm_portfolios.time_index.prices.storage import (
    InterpolatedPricesStorage,
    configured_interpolated_prices_storage,
)


def _autogenerate(engine, provider) -> list:
    with engine.connect() as connection:
        context = MigrationContext.configure(
            connection,
            opts={
                "target_metadata": provider.target_metadata,
                "include_name": provider.include_name,
                "include_object": provider.include_object,
                "compare_type": True,
                "compare_server_default": True,
            },
        )
        return produce_migrations(context, provider.target_metadata).upgrade_ops.ops


def test_a_producer_following_the_skill_template_migrates_only_its_own_tables(
    tmp_path, sqlite_revisions
) -> None:
    class Base(DeclarativeBase):
        metadata = MetaData(naming_convention=sqlalchemy_naming_convention())

    class FollowedIndexTable(PlatformManagedMetaTable, Base):
        __tablename__ = "producer_app__followed_index"
        __metatable_namespace__ = "producer-app"
        __metatable_identifier__ = "producer_app.followed_index"
        __metatable_description__ = "One row per Markets index that the producer follows."

        index_identifier: Mapped[str] = mapped_column(
            String(255),
            ForeignKey(IndexTable.__table__.c.unique_identifier, ondelete="RESTRICT"),
            primary_key=True,
        )

    owned = {"namespace": "producer-app", "storage_app": "producer_app", "base": Base}
    models = [
        FollowedIndexTable,
        configured_time_index_instance(InterpolatedPricesStorage, instance_key="main", **owned),
        configured_portfolio_rebalance_state_storage(instance_key="main", **owned),
        configured_portfolio_calendar_events_storage(instance_key="main", **owned),
        configured_portfolio_event_ledger_storage(instance_key="main", **owned),
        configured_index_values_storage(cadence="1d", **owned),
        configured_interpolated_prices_storage(
            source_time_index_meta_table_uid="source-bars",
            source_cadence="1d",
            upsample_frequency_id=None,
            intraday_bar_interpolation_rule="ffill",
            **owned,
        ),
    ]
    # The provider as the metatable_migrations skill's template builds it: no include hook.
    provider = build_metatable_migration_provider(
        package="producer_app",
        migration_namespace="producer-app",
        script_location="producer_app.migrations:",
        version_location_prefix="producer_app.migrations:versions",
        target_metadata=Base.metadata,
        alembic_registry=build_alembic_version_metatable(
            class_name="ProducerAlembicVersion",
            namespace="producer-app",
            identifier="producer_app.alembic_version",
            schema=None,
            table_name="producer_app__alembic_version",
        ),
        metatable_models=models,
    )
    own_tables = {model.__table__.name for model in models}
    engine = sqlite_revisions.engine(tmp_path / "markets.sqlite", "head")

    changes = _autogenerate(engine, provider)

    assert {change.table_name for change in changes} == own_tables
    created = {change.table_name for change in changes if isinstance(change, ops.CreateTableOp)}
    assert created == own_tables

    # Once they exist, their keys to Markets are in the database and compare equal.
    Base.metadata.create_all(engine)
    inspector = inspect(engine)
    referenced = {
        key["referred_table"] for table in own_tables for key in inspector.get_foreign_keys(table)
    }
    assert referenced == {
        model.__table__.name
        for model in (
            AssetTable,
            CalendarTable,
            IndexFormulaDefinitionTable,
            IndexTable,
            PortfolioTable,
        )
    }
    assert _autogenerate(engine, provider) == []
    engine.dispose()
